EXPLAIN (ANALYZE,BUFFERS) WITH candidates AS (SELECT p.source,p.batch_id,p.external_id FROM civica_poc.proposals p JOIN civica_poc.active_publications ap ON ap.source=p.source AND ap.batch_id=p.batch_id WHERE p.search_label LIKE '%saude%' UNION SELECT p.source,p.batch_id,p.external_id FROM civica_poc.proposals p JOIN civica_poc.active_publications ap ON ap.source=p.source AND ap.batch_id=p.batch_id WHERE p.search_summary LIKE '%saude%' UNION SELECT p.source,p.batch_id,p.external_id FROM civica_poc.proposals p JOIN civica_poc.active_publications ap ON ap.source=p.source AND ap.batch_id=p.batch_id WHERE p.search_type LIKE '%saude%' UNION SELECT p.source,p.batch_id,p.external_id FROM civica_poc.proposals p JOIN civica_poc.active_publications ap ON ap.source=p.source AND ap.batch_id=p.batch_id WHERE p.search_number LIKE '%saude%' UNION SELECT p.source,p.batch_id,p.external_id FROM civica_poc.proposals p JOIN civica_poc.active_publications ap ON ap.source=p.source AND ap.batch_id=p.batch_id JOIN civica_poc.proposal_authors a ON a.source=p.source AND a.proposal_id=p.external_id WHERE a.search_name LIKE '%saude%') SELECT p.source,p.external_id FROM civica_poc.proposals p JOIN candidates c ON c.source=p.source AND c.batch_id=p.batch_id AND c.external_id=p.external_id JOIN civica_poc.active_publications ap ON ap.source=p.source AND ap.batch_id=p.batch_id ORDER BY p.year DESC,p.type,p.number LIMIT 21;
